# Batch Processing Python Script for Document Classification

## Overview
End-to-end Python script pattern for extracting text from mixed document types
and classifying them into categories.

## Full Pipeline Pattern

```python
import subprocess
import os
import json

def extract_pdf_text(filepath, max_pages=2):
    """Extract text from PDF using pdftotext CLI."""
    try:
        result = subprocess.run(
            ['pdftotext', '-l', str(max_pages), filepath, '-'],
            capture_output=True, text=True, timeout=30
        )
        return result.stdout[:3000]
    except Exception:
        return ""

def extract_docx_text(filepath):
    """Extract text from DOCX using python-docx."""
    from docx import Document
    doc = Document(filepath)
    return "\n".join(p.text for p in doc.paragraphs)[:3000]

def extract_pptx_text(filepath):
    """Extract text from PPTX using python-pptx."""
    from pptx import Presentation
    prs = Presentation(filepath)
    texts = []
    for slide in prs.slides:
        for shape in slide.shapes:
            if hasattr(shape, "text"):
                texts.append(shape.text)
    return "\n".join(texts)[:3000]

def extract_text(filepath):
    """Route to appropriate extractor based on file extension."""
    ext = os.path.splitext(filepath)[1].lower()
    if ext == '.pdf':
        return extract_pdf_text(filepath)
    elif ext == '.docx':
        return extract_docx_text(filepath)
    elif ext == '.pptx':
        return extract_pptx_text(filepath)
    return ""

def classify_text(text, keywords_by_category):
    """Score text against keyword sets and return best category."""
    scores = {}
    text_lower = text.lower()
    for cat, keywords in keywords_by_category.items():
        scores[cat] = sum(text_lower.count(kw.lower()) for kw in keywords)
    best = max(scores, key=scores.get)
    return best if scores[best] > 0 else None

# Usage:
# for each file -> extract_text -> classify_text -> record mapping
# then move files according to mapping
```

## Error Handling
- Wrap extraction in try/except to handle corrupt files
- Log failures for manual review
- Use filename as fallback classification signal

